def load() -> pd.DataFrame:
    import pandas as pd
    import numpy as np

    path = 'data/archeology/input/climateMeasurements.xlsx'

    # Read a small preview without headers to find the header row.
    raw = pd.read_excel(path, header=None, dtype=str, nrows=120)

    def norm(x):
        if x is None or (isinstance(x, float) and np.isnan(x)):
            return ''
        return str(x).strip().lower()

    # Heuristic: header row contains 'site' in col0 and 'hole' in col1 (seen in inspect)
    header_row = None
    for i in range(len(raw)):
        v0 = norm(raw.iat[i, 0]) if raw.shape[1] > 0 else ''
        v1 = norm(raw.iat[i, 1]) if raw.shape[1] > 1 else ''
        if v0 == 'site' and v1 == 'hole':
            header_row = i
            break

    if header_row is None:
        # Fallback: any row containing both tokens anywhere
        for i in range(len(raw)):
            row = [norm(v) for v in raw.iloc[i].tolist()]
            if ('site' in row) and ('hole' in row):
                header_row = i
                break

    if header_row is None:
        raise ValueError('Could not locate header row in climateMeasurements.xlsx (expected a row starting with Site, Hole, ...)')

    df = pd.read_excel(path, header=header_row, dtype=str)
    df = df.dropna(how='all')
    # Standardize column names (strip whitespace)
    df.columns = [str(c).strip() for c in df.columns]
    return df
